const envelope = $input.first().json;
const body = envelope.body ?? envelope;
const headers = envelope.headers ?? {};
const expectedKey = 'REPLACE_WITH_SHARED_SECRET';
const receivedKey = String(headers['x-hermes-daily-review-key'] ?? '');
if (expectedKey === 'REPLACE_WITH_SHARED_SECRET' || receivedKey !== expectedKey) {
  throw new Error('Unauthorized Hermes daily review');
}
if (body?.version !== '1.0' || typeof body.report_id !== 'string' || typeof body.date !== 'string') {
  throw new Error('Invalid Hermes daily review payload');
}
if (!Array.isArray(body.todos) || !Array.isArray(body.sipi_ideas) || typeof body.telegram_text !== 'string') {
  throw new Error('Incomplete Hermes daily review payload');
}
const state = $getWorkflowStaticData('global');
state.sentReportIds ??= {};
const duplicate = Boolean(state.sentReportIds[body.report_id]);
const escapeHtml = (value) => String(value ?? '').replace(/[&<>\"']/g, (char) => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[char]));
const todoRows = body.todos.length
  ? body.todos.map((todo, index) => `<li>${index + 1}. ${escapeHtml(todo.item)}｜${escapeHtml(todo.due_date || '未指定')}</li>`).join('')
  : '<li>目前沒有未完成待辦。</li>';
const ideaRows = body.sipi_ideas.length
  ? body.sipi_ideas.map((idea, index) => `<li>${index + 1}. ${escapeHtml(idea.title)}</li>`).join('')
  : '<li>目前沒有待消化的 SI/PI idea。</li>';
const html = `<h2>Hermes 每日盤點｜${escapeHtml(body.date)}</h2><h3>未完成待辦（${body.todos.length}）</h3><ol>${todoRows}</ol><h3>待消化 SI/PI idea（${body.sipi_ideas.length}）</h3><ol>${ideaRows}</ol>`;
return [{json: {...body, duplicate, html}}];

const prepared = $('Validate + Prepare').first().json;
const state = $getWorkflowStaticData('global');
state.sentReportIds ??= {};
state.sentReportIds[prepared.report_id] = new Date().toISOString();
const ids = Object.keys(state.sentReportIds).sort();
for (const id of ids.slice(0, Math.max(0, ids.length - 90))) delete state.sentReportIds[id];
return [{json: {accepted: true, duplicate: false, report_id: prepared.report_id}}];
